DATE='2026-11-14'
BEACON="<!-- Cloudflare Web Analytics --><script type='module' src='https://static.cloudflareinsights.com/beacon.min.js' data-cf-beacon='{\"token\": \"8fda4e0760444de3bb4d8fbd43079a13\"}'></script><!-- End Cloudflare Web Analytics -->"
ADS=json.loads((ROOT/'ads.json').read_text())
def adblock(kind):
 brand='PC WRAP' if kind.startswith('pcwrap') else 'Qualit'
 return '<div class="affiliate-ad affiliate-'+kind+'" aria-label="広告：'+brand+'"><div class="ad-label">広告 / '+brand+'</div>'+ADS[kind]+'</div>'
def esc(s): return html.escape(s,quote=True)
def link(url,label):return f'<a href="{esc(url)}" target="_blank" rel="noopener noreferrer">{label}<span aria-hidden="true"> ↗</span></a>'
def p(t):return '<p>'+t+'</p>'
def section(t,b):return '<section><h2>'+t+'</h2>'+b+'</section>'
def table(head,rows):return '<div class="table-scroll" tabindex="0" role="region" aria-label="比較表。横にスクロールできます"><table><thead><tr>'+''.join('<th scope="col">'+x+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+c+'</td>' for c in r)+'</tr>' for r in rows)+'</tbody></table></div>'
def ul(items):return '<ul>'+''.join('<li>'+i+'</li>' for i in items)+'</ul>'
