articles=[]
def article(slug,tag,title,dek,body,sources,icon):
 articles.append(dict(slug=slug,tag=tag,title=title,dek=dek,body=body,sources=sources,icon=icon))
article('shop-comparison','販売店を比べる','QualitとPC WRAPを比較。保証・返品のどこが違う？','中古ノートは本体価格に加えて、届いた後の対応も購入条件です。保証の年数だけで決めないための比較。',
 section('同じ機種でも、購入条件を揃える',p('CPU、メモリ、SSD、画面解像度が一致していても、外観状態と電池の扱いで選び方は変わります。まず候補の販売ページを2つ開き、構成と状態をメモしてください。店舗ごとのA・B・Cというランクは共通規格として扱わず、各店の説明を読みます。'))+
 section('保証期間と対象を分けて確認',table(['確認項目','Qualit','PC WRAP'],[['基本の保証','対象品は12か月。訳あり品は別条件','対象品は3年。期間によって対応内容が変わる'],['電池など','バッテリー等の消耗部品は対象外','消耗品の対象範囲は保証規約で確認'],['返品を見るとき','不具合時の対応と購入者都合を区別','到着予定日から7日間の返品制度を確認'],['確認先',link(Q,'公式の保証規約'),link(W,'公式の保証・返品条件')]])+p('保証対象の商品か、手元から送る送料を誰が負担するか、修理不能の場合にどうなるかまで確認します。「長期保証だから何でも無料」とは考えないようにします。'))+
 section('外に持ち出すなら、電池の確認を先に',p('購入時の電池容量の選別基準と、購入後の消耗に対する保証は別の話です。QualitにはWindows製品のランク品に関する電池の選別案内がありますが、対象外区分もあります。商品ページと品質説明をセットで読み、購入候補への適用を確認してください。'))+
 section('比較メモの作り方',ul(['税込本体価格と送料を足して、支払総額を記録する。','キズの位置や写真が共通画像か個体画像かを確認する。','保証・返品の期限の起点、連絡方法、除外事項を記録する。','Officeが必要なら、製品名・利用条件・追加費用を別に確認する。']))+
 section('どちらを選ぶか迷ったら',p('同じ構成の在庫が両店にあるときは、持ち運びが多いなら電池状態の説明、自宅中心なら価格と画面、故障時の負担を抑えたいなら保証範囲を優先して比べます。このページは公式条件の調査で、実機の使用感や店舗の対応速度を評価したレビューではありません。')),
 [(Q,'Qualit：保証規約'),(W,'PC WRAP：保証・返品規約'),(QUALITY,'Qualit：品質・検査の案内')],'shield')
article('budget-50000','予算から選ぶ','3〜5万円の仕事用中古ノート。価格以外に見る6項目','文書・表計算・メール・オンライン会議。毎日の使い方から、必要な構成を絞ります。',
 section('使うアプリを先に書き出す',p('「仕事用」でも、ブラウザと文書作成だけの場合と、大きな表計算ファイルを扱いながら会議をする場合では条件が違います。会社指定のアプリやセキュリティ要件、個人所有端末の利用可否を先に確認しましょう。予算内でも必要なアプリが動かなければ目的に合いません。'))+
 section('価格を比べるときの6項目',table(['項目','確認する内容'],[['CPU','Core i5などの名称に加えて、10210U等の末尾まで確認'],['メモリ','現在の容量と後から増設できるか'],['SSD','必要な容量、保存データと空き容量'],['画面','大きさだけでなく解像度と状態'],['電池・付属品','容量の記載、ACアダプター、カメラ'],['OS・保証','Windows 11の要件、返品・保証の対象範囲']]))+
 section('予算配分の例',p('たとえば総予算5万円なら、本体だけに5万円を使わず、送料、必要なソフト、マウスや会議用機器の費用を差し引いてから本体の上限を決めます。これは予算の組み方であり、掲載機種がその金額で買えるという保証ではありません。'))+
 section('中古の構成例から候補を作る',p('比較候補としてThinkPad L13（第10世代インテル）とLatitude 5310を取り上げています。いずれも機種名だけで購入せず、販売個体のメモリ・画面・状態を確認します。年式の近い別機種や新品の価格も併せて確認し、中古であること自体をお得さの根拠にしないようにします。'))+
 section('Windows 11搭載と要件適合は別に確認',p('Windows 11には対応プロセッサやTPMなどの要件があります。販売ページの「Windows 11搭載」という表記だけで判断せず、正確なCPU型番、メーカーの情報、販売店の説明を照合します。最小要件を満たすことと、使うアプリで快適に動くことも別です。'))+
 section('候補を2台まで絞る',p('まず用途に必要な条件を満たす個体を残し、次に総額と返品条件を比べます。使わない機能に予算を使うより、毎日目にする画面と入力機器の状態を重視する方法もあります。購入前は「候補の型番・構成・保証」を保存して、届いたものと照合できるようにしましょう。')),
 [(MS,'Microsoft：Windows 11の要件'),(L,'Lenovo：ThinkPad L13仕様'),(D,'Dell：Latitude 5310メモリー仕様')],'budget')
article('thinkpad-l13','機種から選ぶ','ThinkPad L13の中古選び。世代・メモリ・画面の確認ポイント','「L13」という名前だけでは同じ構成になりません。第10世代インテル搭載モデルを中心に確認します。',
 section('最初に世代とCPU型番を合わせる',p('中古の商品名には、世代の記載が省かれていることがあります。本記事の主な対象は初代のThinkPad L13（第10世代インテル）です。Gen 2以降やYogaなど別のモデルの仕様を混ぜず、販売ページの製品番号とCPU型番を見てください。'))+
 section('メモリは購入前に決める',p('Lenovoの初代L13仕様ではメモリは基板に固定され、増設不可です。安い8GBモデルを買って後で16GBにする前提では選べません。複数アプリを使う予定なら、必要な容量を購入前に決めることをおすすめします。')+table(['見る場所','チェックすること'],[['商品名','L13・世代・CPU型番'],['メモリ欄','8GBか16GBか。容量を必ず確認'],['液晶欄','解像度、画面のキズや色むら'],['状態欄','キーボード、端子、ヒンジ、電池の説明']]))+
 section('画面と入力機器を見落とさない',p('同じ13.3型でも、解像度やタッチ対応の違いがあります。文章や表を並べて使うなら、解像度の記載を読みます。キーボードの文字消え・テカリ、パームレストの摩耗、ヒンジの説明も確認しましょう。共通の製品画像だけで中古個体の状態は判断できません。'))+
 section('掲載価格をそのまま相場にしない',p('中古の掲載価格は、構成と個体の状態に左右されます。検索結果に残った価格だけでは、現在も同じ条件で購入できるとは限りません。候補は販売店の最新ページで再確認し、在庫がない商品を相場の根拠にしないようにしましょう。'))+
 section('L13を候補に残す条件',p('必要なメモリ容量が最初から搭載され、画面・電池・外観・保証が許容できる個体を探します。仕様だけで打鍵感や会議中の動作音は評価できないため、これらの使用感は未検証です。購入後の使い勝手が心配なら、購入者都合返品の条件も比較してください。')),
 [(L,'Lenovo：初代ThinkPad L13仕様（PDF）'),('https://www.pcwrap.com/item/index/?keyword=THINKPAD%20L13','PC WRAP：L13の掲載を確認')],'laptop')
article('latitude-5310','機種から選ぶ','Latitude 5310の中古選び。メモリ構成と状態を揃えて比較','CPUが同じでも、液晶・SSD・電池・外観で条件は変わります。販売個体を読むためのガイド。',
 section('通常モデルと別モデルを混ぜない',p('Latitude 5310と、名称が似た2-in-1モデルは区別します。販売ページの型番と機種に合うメーカー仕様を参照し、別モデルの重量や画面、端子の情報を流用しないようにします。'))+
 section('メモリは容量だけでなく内訳を見る',p('Dellの通常モデルの仕様には2本のSoDIMMスロットが記載されています。販売個体が8GB×2なのか16GB×1なのかで空きスロットの状況が変わります。増設を予定するなら、購入時点の構成と販売店の保証への影響を確認してください。作業が不安なら最初から必要な容量の個体を選ぶ方法があります。'))+
 section('販売一覧で確認できた構成例',table(['項目','確認例'],[['販売店','Be-Stock'],['CPU','Core i5-10310U'],['メモリ・SSD','16GB・256GB'],['画面','13.3型・フルHD・タッチ対応'],['状態','Bランク、底面塗装剥がれの記載'],['保証','1年保証の表示']])+p('2026年11月14日に公式一覧で確認した構成例です。販売店独自の状態区分で、機種全体の標準仕様ではありません。価格・送料・在庫は販売ページの最新表示を確認してください。'))+
 section('同じ機種でも安い個体との違いを読む',p('8GBと16GB、SSD128GBと256GB、フルHDとそれ以外の画面を一緒に並べると、価格差の理由が分からなくなります。まず構成を合わせ、次にキズや液晶状態、電池情報、保証の違いを比べます。価格だけの順位付けは避けます。'))+
 section('受け取った日の確認メモ',ul(['注文したCPU・メモリ・SSD・OSと一致しているか。','液晶、キーボード、タッチパッド、充電端子に問題がないか。','自分が使うカメラ・マイク・ネット接続を確認する。','不具合があれば分解せず、保証期限内に販売店へ連絡する。']))+p('当サイトでは実機測定を行っていないため、電池の持ち時間やアプリの処理速度を断定していません。'),
 [(D,'Dell：通常モデルのメモリー仕様'),('https://www.be-stock.com/shop2/note/dell/latitude/5310.html','Be-Stock：Latitude 5310の掲載')],'laptop')
article('memory-8gb-16gb','購入前の確認','中古ノートの8GBと16GB。使い方と増設可否から選ぶ','必要な容量はアプリと同時作業で変わります。OSの最小要件と、日々の仕事の余裕を分けて考えます。',
 section('普段の同時作業を思い出す',p('ブラウザのタブ、メール、文書、オンライン会議を同時に使うかを書き出してください。メモリは今使っている作業のための領域で、SSDの保存容量とは役割が違います。SSDが大きくてもメモリ不足を同じように補えるわけではありません。'))+
 section('8GBと16GBを選ぶための目安',table(['使い方','検討の方向'],[['少数のアプリを順に使う','8GBも候補。利用アプリの推奨条件を確認'],['会議・ブラウザ・表計算を並行','16GBを優先して比較するのが当サイトの提案'],['大きなデータ・制作ソフト','アプリの推奨要件に合わせる。16GBで十分とは限らない']])+p('これは用途に応じた編集上の目安です。同じアプリでもファイルの規模や設定で負荷は変わり、容量だけで快適さは決まりません。CPUやSSD、通信環境も含めて選びます。'))+
 section('後から増やせるかが価格差を変える',p('初代ThinkPad L13はメモリ固定型、通常のLatitude 5310はメモリスロットを備える仕様です。ただし別世代や別モデルでは条件が変わるため、機種名の一部だけで判断しないようにします。増設の費用と工賃、保証の扱いを足すと、最初から16GBの個体を買うほうが納得しやすい場合もあります。'))+
 section('最小要件をおすすめ基準にしない',p('MicrosoftのWindows 11要件には4GB以上というメモリ条件がありますが、これは日々の仕事に必要な余裕を保証する値ではありません。OSが起動する条件と、使うアプリの条件を別に確認しましょう。'))+
 section('いまのPCがあるなら確認する',p('普段どおりに作業しているときのメモリ使用状況を、Windowsのタスクマネージャーで確認する方法があります。使用率だけで原因を決めつけず、動作が重くなる場面もメモすると候補選びに役立ちます。当サイトには容量別の実測比較はなく、何倍速いといった数値評価は掲載していません。')),
 [(MS,'Microsoft：Windows 11要件'),(L,'Lenovo：メモリ構成'),(D,'Dell：メモリ構成')],'memory')
article('battery-warranty','購入前の確認','中古ノートの電池。「容量の基準」と「保証」を分けて確認','買うときの電池状態と、買った後に交換してもらえる条件は別です。持ち運び用の購入前チェック。',
 section('容量80％と書いてあっても、8時間使えるとは限らない',p('電池容量の割合は、使い方ごとの連続動作時間とは異なります。画面の明るさ、会議や動画再生、無線通信などによって消費は変わります。新品時のカタログ時間に容量の割合を掛けて、実際の持ち時間と断定することはできません。'))+
 section('購入前に分けて読む3つの情報',table(['区分','確認すること'],[['販売時の状態','容量・検査基準が購入する区分に適用されるか'],['使用後の保証','消耗や故障のどこまでが対象か'],['交換の見通し','部品・費用・修理受付先を確認できるか']]))+
 section('ランク品と訳あり品で条件が違うことがある',p('販売店の品質説明は、対象となる製品区分を確認します。ある区分の電池検査基準を、同じ店の全商品へ当てはめることはできません。個別ページに電池情報がなければ、推測で良好とせず、購入前に販売店へ問い合わせましょう。'))+
 section('長期保証でも消耗品は別扱い',p('保証の見出しが1年・3年でも、電池や付属品は別の扱いになることがあります。Qualitの保証規約にも消耗部品の除外があります。PC WRAPも商品と期間に応じた規約を確認し、購入時の状態と購入後の対応を分けて記録してください。'))+
 section('持ち運びと自宅用で優先項目を変える',p('外出先で電源を使えないなら、電池状態の情報がある個体を優先するのが当サイトの提案です。自宅で電源に接続して使う場合も、充電できるかや膨張などの異常がないかは重要です。異常を感じたら使用をやめ、販売店やメーカーへ相談してください。'))+
 section('届いた後は返品期間内に確認する',p('販売ページの記載と、届いた個体の状態を照合します。電池情報を記録し、すぐ電源が落ちるなどの症状は発生状況とともに販売店へ連絡します。自己分解や部品交換を始める前に、返品・保証条件を確認しておきましょう。')),
 [(Q,'Qualit：保証規約'),(QUALITY,'Qualit：品質説明'),(W,'PC WRAP：保証条件')],'battery')


article('thinkpad-l13-vs-latitude-5310','2機種を比較','ThinkPad L13とLatitude 5310を比較。中古で迷ったときの選び方','同じ予算で見つかる2台。メモリの増設、画面、電池、保証を揃えて、手元の候補を比べます。',
 section('比較するモデルを最初に揃える',p('中古の検索結果ではThinkPad L13の複数世代やYoga、Latitude 5310の通常モデルと2-in-1が混ざることがあります。本記事は初代ThinkPad L13（第10世代インテル）と通常のLatitude 5310を対象とします。中古の販売個体はメーカー出荷時の構成と異なる場合があるため、商品名だけで仕様を決めつけないでください。'))+
 section('大きな違いはメモリの増設方法',table(['項目','ThinkPad L13（初代）','Latitude 5310（通常モデル）'],[['メモリ構造','基板に固定。増設不可','SoDIMMスロット2本'],['メーカー仕様上の構成','4GB・8GB・16GB','最大32GB'],['購入時に気をつけること','必要な容量を最初に選ぶ','現在の容量と枚数、空きスロットを確認'],['後から容量を増やす場合','増設を前提にしない','対応部品・作業費・販売店保証への影響を確認']])+p('この違いから、後でメモリを増やす余地を残したいならLatitude 5310を検討しやすい、というのが当サイトの判断です。ただし、自分で増設する必要がない場合は、最初から必要な容量を備えるL13も比較候補になります。増設の可否だけで機種全体の優劣は決まりません。'))+
 section('同じCore i5でもCPU型番まで読む',p('Core i5という名称だけで同じ性能と判断しないようにします。候補がi5-10210Uとi5-10310Uなら、その違いを記録したうえでメモリ・SSD・画面も照合します。本記事では実機の速度測定をしていないため、何％速い、会議が必ず快適といった評価はしていません。利用するアプリの推奨要件を満たすかも別に確認します。'))+
 section('液晶・電池・キーボードは個体ごとの比較',p('同じ機種名でも画面の解像度、タッチ対応、電池の状態、キーボードの摩耗で使い勝手が変わります。持ち出すなら電池情報、自宅で文章や表を扱うなら画面と入力機器を重点的に確認しましょう。メーカーの製品写真は、中古個体のキズや電池の劣化を示すものではありません。')+ul(['液晶：解像度、キズ、色むら、表示不良の記載。','電池：購入時の検査基準と、購入後の保証の違い。','入力機器：文字消え、テカリ、タッチパッドの状態。','付属品：対応ACアダプター、必要なケーブルの有無。']))+
 section('価格差は購入後の費用まで含める',p('仮に本体価格が安くても、送料、必要なソフト、増設や交換の費用を加えると比較結果が変わります。Office付きの場合も、製品名とライセンス条件を確認します。価格の安い一台と状態の良い一台を比べるときは、何に差額を払うのかを言葉にしてから判断してください。')+table(['確認欄','候補A','候補B'],[['正確な機種・CPU','販売ページから転記','販売ページから転記'],['メモリ・SSD・画面','容量と解像度を確認','容量と解像度を確認'],['状態・電池','個体の説明を記録','個体の説明を記録'],['支払総額・保証','送料・ソフト・返品も確認','送料・ソフト・返品も確認']]))+
 section('今の用途と、後から必要になることを分ける',p('容量を後から変える予定がなく、条件のよい16GB個体が見つかればL13を候補にできます。メモリの増設余地を重視するならLatitude 5310の現構成を確認します。どちらも、電池や画面の状態、販売店の返品条件が合わなければ別の個体を探すことをおすすめします。増設できる機種でも、不具合のある個体を選んでよい理由にはなりません。'))+
 section('機種別の確認項目も読む',p('<a href="/thinkpad-l13/">ThinkPad L13の中古購入ガイド</a>では世代とメモリ固定型の注意点を、<a href="/latitude-5310/">Latitude 5310の中古購入ガイド</a>ではメモリ構成と個体の読み方を整理しています。店舗の条件に迷ったら、<a href="/shop-comparison/">QualitとPC WRAPの保証・返品比較</a>も確認してください。')),
 [(L,'Lenovo：初代ThinkPad L13の公式仕様'),(D,'Dell：Latitude 5310のメモリー公式仕様')],'laptop')

