finder='<section class="finder" aria-labelledby="finder-title"><div><span class="eyebrow" style="color:#d9c192">START HERE</span><h2 id="finder-title">どこから読めばいい？</h2><p>いま気になっていることから、<br>役に立つガイドを選びます。</p></div><div><label for="interest">知りたいこと</label><select id="interest"><option value="thinkpad-l13-vs-latitude-5310">L13とLatitude 5310で迷っている</option><option value="budget-50000" selected>予算内で一台を選びたい</option><option value="shop-comparison">販売店の保証・返品を比べたい</option><option value="thinkpad-l13">ThinkPad L13を検討している</option><option value="latitude-5310">Latitude 5310を検討している</option><option value="memory-8gb-16gb">8GBと16GBで迷っている</option><option value="battery-warranty">電池の状態が心配</option></select><a class="btn" id="finder-link" href="/budget-50000/">このガイドを読む →</a></div></section>'
check='<section class="contact-callout checklist" style="margin-top:35px"><span class="eyebrow">BEFORE YOU BUY</span><h2>購入前の5つの確認</h2>'+''.join('<label><input type="checkbox">'+s+'</label>' for s in ['CPU・メモリ・SSDの構成を確認した','画面の解像度と個体の状態を読んだ','電池の記載とACアダプターを確認した','保証と返品条件を確認した','送料・必要ソフトを含む総額を確認した'])+'<output id="check-status" aria-live="polite">0 / 5 項目を確認</output><p class="meta">チェックはこのページを開いている間だけ有効です。</p></section>'
render('','仕事用中古ノートの選び方・販売店比較','予算3〜5万円の仕事用中古ノートを、構成・外観・電池・保証から比較。ThinkPad L13、Latitude 5310、QualitとPC WRAPの購入条件を整理。','<div class="wrap">'+hero+'<div class="principles"><span><strong>01</strong> 公式仕様・規約を確認</span><span><strong>02</strong> 構成と状態を分けて比較</span><span><strong>03</strong> 未検証の使用感を断定しない</span></div>'+finder+'<section id="guides"><div class="section-title"><h2>選ぶための7つのガイド</h2><small>調べたいことから、少しずつ。</small></div><div class="guide-grid">'+''.join(card(a) for a in articles)+'</div></section>'+check+'<div class="note">掲載情報は2026年11月14日確認。中古商品の価格・在庫・状態は個体ごとに変わります。一部に成果報酬型の広告リンクを含みます。広告の有無だけで比較結果を決めません。</div></div>')
policies={
'about':('このサイトについて・編集方針','しごとPCくらべの運営目的と情報の確認方法。',section('運営と目的',p('運営：しごとPCくらべ。文書・表計算・メール・オンライン会議などに使う中古ノートを探す方に向けた独立した情報サイトです。販売店やメーカーの公式サイトではなく、商品の販売・修理は行っていません。'))+section('情報の確認方法',p('メーカー仕様、販売店の利用ガイド、保証規約などを参照し、確認日と参照先を掲載します。元の仕様と中古個体の構成が異なる場合は個体の販売説明を確認します。実機を使っていない記事は購入ガイドとして掲載し、使用体験・測定値・口コミを作りません。'))+section('比較・紹介の基準',p('用途、構成、状態、電池、保証・返品条件を比較します。広告報酬だけを理由に順位を付けず、条件の異なる商品を同条件のように並べません。未確認事項は未確認と記し、価格・在庫が確定しない情報で購入を促しません。'))+section('訂正と更新',p('条件の変更や誤りに気づいた場合は確認のうえ修正します。掲載内容へのご指摘はお問い合わせ窓口へお寄せください。購入契約や保証請求については購入先へ直接ご連絡ください。'))),
'contact':('お問い合わせ','記事の誤りや掲載内容に関する連絡窓口。',section('記事へのご指摘・ご連絡',p('当サイトの記事の誤り、情報更新のご連絡、掲載内容へのお問い合わせは、運営用GitHubリポジトリのIssuesで受け付けます。投稿にはGitHubアカウントが必要です。')+'<div class="contact-callout">'+link('https://github.com/928ghsdvhh-beep/shigoto-pc-guide/issues/new','GitHubのお問い合わせ画面を開く')+'</div>')+section('ご連絡に含める内容',ul(['該当する記事のURL','修正・確認を希望する箇所','確認できる公式情報のURL（ある場合）'])+p('Issuesの投稿は公開されます。氏名、メールアドレス、住所、注文番号、パスワードなどの個人情報・機密情報は書き込まないでください。'))+section('当サイトで対応できない内容',p('商品購入、配送、返品、修理、保証の個別手続きは販売店へお問い合わせください。当サイトでは注文情報を保有していません。すべてのお問い合わせへの回答や回答期限をお約束するものではありません。'))),
'privacy':('プライバシーポリシー','当サイトでの情報の取り扱い。',section('当サイトが取得する情報',p('このサイトには、氏名やメールアドレスを入力する独自フォーム、会員登録機能、決済機能はありません。購入前チェックの入力内容は外部へ送信せず、サーバーや端末へ保存しません。運営はしごとPCくらべです。'))+section('アクセス情報',p('当サイトは株式会社ファンコミュニケーションズのA8.net広告を配信しています。広告表示や成果計測に際し、広告配信事業者がCookie等を利用し閲覧・クリック等の情報を取得する場合があります。アクセス状況の把握と記事改善のため、Cloudflare Web Analyticsを利用しています。ホスティング事業者が配信・セキュリティ維持のためアクセス情報を処理する場合があります。データの取り扱いはCloudflareのプライバシーポリシーをご確認ください。利用サービスを変更する際は本ページを見直します。'))+section('Cloudflare Web Analytics',p('ページ閲覧などの利用状況を把握し、サイトの改善に利用します。提供元はCloudflareです。')+link('https://www.cloudflare.com/privacypolicy/','Cloudflareのプライバシーポリシー'))+section('外部サイトと問い合わせ',link('https://www.fancs.com/privacy','ファンコミュニケーションズのプライバシーポリシー')+p('外部リンク先には各事業者のプライバシーポリシーが適用されます。お問い合わせに利用するGitHub Issuesは公開の投稿欄です。個人情報を書き込まないでください。リンク先での情報の扱いは各サービスをご確認ください。'))+section('改定',p('情報の取り扱いや利用サービスの変更に応じて内容を見直します。制定・更新日：2026年11月14日。お問い合わせは当サイトの連絡窓口をご利用ください。'))),
'advertising':('広告・免責事項','広告リンクと比較情報の扱い。',section('広告の掲載状況',p('当サイトはA8.netを通じてQualit・PC WRAPの成果報酬型広告を掲載しています。広告リンクを経由した購入等により、当サイトに紹介料が支払われる場合があります。広告以外の外部リンクは情報・販売条件の確認用です。'))+section('広告と比較の区別',p('広告リンクのあるページに広告を含むことを表示します。広告主・ASPから提供された正規のコードを使用します。広告内の文言は広告主の表現であり、当サイトが全販売店の最安値を保証するものではありません。広告報酬の有無だけで比較結果を決めません。'))+section('購入に関する注意',p('価格・送料・在庫・商品の状態・保証条件は変わることがあります。中古品には個体差があり、同じ機種名でも構成が異なります。契約前に販売店の最新表示を確認し、ご自身の用途に合うか判断してください。'))+section('免責事項',p('正確な情報の提供に努めますが、完全性や将来の状態を保証するものではありません。本サイトの情報は個別商品の動作保証や業務適合性の保証ではなく、購入契約の当事者は購入者と販売事業者です。法令上認められる範囲で責任を取り扱います。')))
}
